edits.new:
if (
    bestCompleted.depth > 0 &&
    current.hasMove &&
    bestCompleted.hasMove &&
    sameMove(
        current.bestMove,
        bestCompleted.bestMove
    )
    ) {
    ++stableBestMoveDepths;
}
else {
    stableBestMoveDepths = 0;
}

if (
    bestCompleted.depth > 0 &&
    current.score == previousScore
    ) {
    ++stableScoreDepths;
}
else {
    stableScoreDepths = 0;
}

bestCompleted =
    current;

previousScore =
    current.score;
